[{"order":1,"type":"heading","text":"Authentication & Authorization Mechanisms in Automation Testing"},{"order":2,"type":"paragraph","text":"Modern web applications and APIs rely heavily on robust security mechanisms to protect sensitive data. As an automation engineer, validating secured endpoints requires a solid understanding of how Authentication (who you are) and Authorization (what you can do) work. This tutorial covers the implementation of API Keys, JSON Web Tokens (JWT), and OAuth 2.0 within your test automation frameworks."},{"order":3,"type":"subheading","text":"1. API Keys in Test Automation"},{"order":4,"type":"paragraph","text":"API keys are the simplest form of authentication. They are typically passed via request headers, query parameters, or cookies. While easy to implement, they offer minimal security if exposed."},{"order":5,"type":"code","text":"const axios = require('axios');

async function testWithApiKey() {
    try {
        const response = await axios.get('https://api.example.com/data', {
            headers: {
                'x-api-key': 'your_secure_api_key_here'
            }
        });
        console.log('Status:', response.status);
    } catch (error) {
        console.error('Authentication Failed:', error.response.status);
    }
}"},{"order":6,"type":"subheading","text":"2. JSON Web Tokens (JWT)"},{"order":7,"type":"paragraph","text":"JWT is an open standard that defines a compact and self-contained way for securely transmitting information between parties as a JSON object. In test automation, you often acquire a JWT by sending credentials to a login endpoint and then passing that token in the Authorization header as a Bearer token for subsequent requests."},{"order":8,"type":"code","text":"const request = require('supertest');
const app = 'https://api.example.com';

async function testProtectedEndpoint() {
    // Step 1: Authenticate to get JWT
    const authResponse = await request(app)
        .post('/login')
        .send({ username: 'test_user', password: 'secure_password' });

    const token = authResponse.body.token;

    // Step 2: Use JWT in Authorization header
    const dataResponse = await request(app)
        .get('/dashboard')
        .set('Authorization', `Bearer ${token}`);

    if (dataResponse.status === 200) {
        console.log('JWT Authentication Successful');
    }
}"},{"order":9,"type":"subheading","text":"3. OAuth 2.0 Authorization Code Flow"},{"order":10,"type":"paragraph","text":"OAuth 2.0 is an authorization framework that enables applications to obtain limited access to user accounts. In automated API testing, the Client Credentials grant type or Password grant type is frequently used because they do not require human browser interaction."},{"order":11,"type":"code","text":"import requests

def get_oauth_token():
    token_url = 'https://auth.example.com/oauth/token'
    payload = {
        'grant_type': 'client_credentials',
        'client_id': 'your_client_id',
        'client_secret': 'your_client_secret'
    }
    response = requests.post(token_url, data=payload)
    return response.json().get('access_token')"},{"order":12,"type":"subheading","text":"Best Practices for Handling Auth in Automation"},{"order":13,"type":"bullet_point","text":"Never hardcode credentials, API keys, or secrets directly in your test scripts. Always use environment variables or secret managers."},{"order":14,"type":"bullet_point","text":"Implement a global setup or beforeEach hook to fetch tokens dynamically rather than generating a new token for every single test case."},{"order":15,"type":"bullet_point","text":"Handle token expiration gracefully by building automated refresh token logic into your HTTP client wrappers."}]
